// extractGoSymbols parses a single Go file and appends symbol nodes plus
// `contains` edges from the file node to each symbol. Returns the number of
// symbol nodes added.
//
// The POC ships function, method, type, struct, and interface symbols. Tests
// (Test*/Benchmark*/Fuzz*) are tagged as SymbolTest so hotspots and tour
// surfaces can hide them when desired. Imports declarations are emitted as
// EdgeImports with To set to a synthetic `pkg:<path>` node so cross-file
// reachability lookups don't require resolving the importing file's actual
// dependency on disk.
func extractGoSymbols(slice *graph.Slice, relPath, fileID, absPath string) (int, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, absPath, nil, parser.SkipObjectResolution|parser.ParseComments)
	if err != nil {
		return 0, fmt.Errorf("parse %s: %w", relPath, err)
	}

	added := 0
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			added += emitFunc(slice, relPath, fileID, fset, d)
		case *ast.GenDecl:
			added += emitGenDecl(slice, relPath, fileID, fset, d)
		}
	}
	emitImportEdges(slice, fileID, file)
	return added, nil
}

// emitImportEdges turns each `import "path/to/pkg"` declaration into a
// synthetic NodePackage node (id `pkg:<import-path>`) plus a `imports` edge
// from the importing file. Synthetic nodes deduplicate by ID so a popular
// import (e.g. `fmt`) shows up exactly once across the whole structural slice.
func emitImportEdges(slice *graph.Slice, fileID string, file *ast.File) {
	if file == nil {
		return
	}
	for _, imp := range file.Imports {
		if imp == nil || imp.Path == nil {
			continue
		}
		// imp.Path.Value includes the surrounding quotes; trim them.
		raw := imp.Path.Value
		if len(raw) >= 2 && raw[0] == '"' && raw[len(raw)-1] == '"' {
			raw = raw[1 : len(raw)-1]
		}
		if raw == "" {
			continue
		}
		pkgID := "pkg:" + raw
		slice.Nodes = append(slice.Nodes, graph.Node{
			ID:   pkgID,
			Type: graph.NodePackage,
			Name: raw,
		})
		slice.Edges = append(slice.Edges, graph.Edge{
			ID:   "e:imports:" + fileID + "->" + pkgID,
			From: fileID,
			To:   pkgID,
			Type: graph.EdgeImports,
		})
	}
}

