// dedupeSliceNodes preserves first-seen order while removing duplicate node
// IDs. Used after Scan because import-edge emission produces a fresh
// pkg:<import-path> node per importing file.
func dedupeSliceNodes(slice *graph.Slice) {
	if slice == nil || len(slice.Nodes) == 0 {
		return
	}
	seen := make(map[string]struct{}, len(slice.Nodes))
	out := slice.Nodes[:0]
	for _, n := range slice.Nodes {
		if _, dup := seen[n.ID]; dup {
			continue
		}
		seen[n.ID] = struct{}{}
		out = append(out, n)
	}
	slice.Nodes = out
}

