func buildTimeline(infos []checkpoint.CommittedInfo) *graph.Timeline {
	if len(infos) == 0 {
		return &graph.Timeline{Events: []graph.TimelineEvent{}}
	}
	sorted := make([]checkpoint.CommittedInfo, len(infos))
	copy(sorted, infos)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].CreatedAt.Before(sorted[j].CreatedAt)
	})

	// Track which files have been seen at least once across the chronological
	// sweep so each timeline event distinguishes "introduced" (first time
	// this file appears) from "modified" (subsequent touches). This matches
	// the spec's "emit graph deltas for introduced/touched/removed nodes
	// and edges" requirement.
	seenFile := map[string]struct{}{}
	events := make([]graph.TimelineEvent, 0, len(sorted)*2)
	for _, info := range sorted {
		introduced := []string{}
		modified := []string{}
		for _, raw := range info.FilesTouched {
			key := "file:" + raw
			if _, ok := seenFile[key]; ok {
				modified = append(modified, key)
			} else {
				seenFile[key] = struct{}{}
				introduced = append(introduced, key)
			}
		}
		base := graph.TimelineEvent{
			At:           info.CreatedAt.UTC().Format(time.RFC3339),
			CheckpointID: info.CheckpointID.String(),
			SessionID:    info.SessionID,
			Attrs: map[string]any{
				"agent":             string(info.Agent),
				"checkpoints_count": info.CheckpointsCount,
			},
		}
		if len(introduced) > 0 {
			ev := base
			ev.Kind = "introduced"
			ev.NodeIDs = introduced
			events = append(events, ev)
		}
		if len(modified) > 0 {
			ev := base
			ev.Kind = "modified"
			ev.NodeIDs = modified
			events = append(events, ev)
		}
		if len(introduced) == 0 && len(modified) == 0 {
			// Checkpoint with no file telemetry — keep one event so the
			// timeline still surfaces the cp itself for replay/dashboard.
			ev := base
			ev.Kind = "checkpoint"
			events = append(events, ev)
		}
	}
	return &graph.Timeline{Events: events}
}

