func TestScan_GoImportsEmitPackageNodesAndEdges(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	writeFile(t, dir, "a.go", `package svc

import (
	"fmt"
	"strings"
)

func use() string { return fmt.Sprintf("%s", strings.ToLower("X")) }
`)
	writeFile(t, dir, "b.go", `package svc

import "fmt"

func other() { fmt.Println("hi") }
`)

	res, err := Scan(context.Background(), dir)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}

	// Expect deduped pkg:fmt and pkg:strings nodes despite two files importing fmt.
	wantPkgs := map[string]bool{"pkg:fmt": false, "pkg:strings": false}
	for _, n := range res.Slice.Nodes {
		if n.Type == graph.NodePackage {
			if _, ok := wantPkgs[n.ID]; ok {
				wantPkgs[n.ID] = true
			}
		}
	}
	for id, seen := range wantPkgs {
		if !seen {
			t.Errorf("missing package node %s", id)
		}
	}
	// No duplicate package nodes after dedupe pass.
	pkgCounts := map[string]int{}
	for _, n := range res.Slice.Nodes {
		if n.Type == graph.NodePackage {
			pkgCounts[n.ID]++
		}
	}
	for id, n := range pkgCounts {
		if n != 1 {
			t.Errorf("package node %s appears %d times; want 1 (dedupe failed)", id, n)
		}
	}
	// Edges: a.go imports fmt + strings; b.go imports fmt only.
	wantEdges := []struct{ from, to string }{
		{"file:a.go", "pkg:fmt"},
		{"file:a.go", "pkg:strings"},
		{"file:b.go", "pkg:fmt"},
	}
	for _, want := range wantEdges {
		found := false
		for _, e := range res.Slice.Edges {
			if e.Type == graph.EdgeImports && e.From == want.from && e.To == want.to {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("missing imports edge %s -> %s", want.from, want.to)
		}
	}
}

