// stubCheckpointReader implements CheckpointReader for the on-demand endpoint
// tests. It avoids spinning up a real git repo while still exercising the
// path-parsing + JSON-shape contract.
type stubCheckpointReader struct {
	byID map[string]*checkpoint.CheckpointSummary
}

func (s *stubCheckpointReader) ReadCommitted(_ context.Context, cpID id.CheckpointID) (*checkpoint.CheckpointSummary, error) {
	if s == nil || s.byID == nil {
		return nil, errors.New("stub: not configured")
	}
	return s.byID[cpID.String()], nil
}

func newHandlerWithReader(t *testing.T, reader CheckpointReader) (*Server, http.Handler) {
	t.Helper()
	store := makeStore(t)
	srv, err := New(store, reader)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	mux := http.NewServeMux()
	srv.RegisterHandlers(mux)
	return srv, mux
}

func TestServer_CheckpointDetail_RoundTripsMetadata(t *testing.T) {
	t.Parallel()

	cpID := id.MustCheckpointID("a1b2c3d4e5f6")
	reader := &stubCheckpointReader{
		byID: map[string]*checkpoint.CheckpointSummary{
			"a1b2c3d4e5f6": {
				CheckpointID:     cpID,
				Strategy:         "manual-commit",
				Branch:           "main",
				CheckpointsCount: 4,
				FilesTouched:     []string{"a.go", "b.go"},
			},
		},
	}
	srv, h := newHandlerWithReader(t, reader)

	rec := httptest.NewRecorder()
	req := httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/api/checkpoint/a1b2c3d4e5f6", http.NoBody)
	req.Header.Set("Authorization", "Bearer "+srv.Token())
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("status=%d; want 200", rec.Code)
	}
	var got CheckpointDetail
	body, readErr := io.ReadAll(rec.Body)
	if readErr != nil {
		t.Fatalf("read body: %v", readErr)
	}
	if err := json.Unmarshal(body, &got); err != nil {
		t.Fatalf("decode: %v\nraw=%s", err, body)
	}
	if got.CheckpointID != "a1b2c3d4e5f6" {
		t.Errorf("CheckpointID=%q; want a1b2c3d4e5f6", got.CheckpointID)
	}
	if got.CheckpointsCount != 4 {
		t.Errorf("CheckpointsCount=%d; want 4", got.CheckpointsCount)
	}
	if got.Strategy != "manual-commit" || got.Branch != "main" {
		t.Errorf("Strategy/Branch wrong: %+v", got)
	}
	if len(got.FilesTouched) != 2 {
		t.Errorf("FilesTouched=%v; want 2 entries", got.FilesTouched)
	}
}

